<script setup lang="ts">
import { AudioLines, Pause, Play, Heart, Plus } from '@lucide/vue'
import type { Track } from '../../src/types'
type PreviewTrack = Track & { key: string }
defineProps<{ tracks: PreviewTrack[]; currentKey: string; selectedKey: string | null; playing: boolean; favorites: Set<string> }>()
const emit = defineEmits<{ select: [key: string]; play: [track: PreviewTrack]; toggle: [track: PreviewTrack]; album: [key: string]; like: [key: string]; queue: [track: PreviewTrack] }>()
const formatTime = (seconds: number) => `${Math.floor(seconds / 60)}:${String(Math.floor(seconds % 60)).padStart(2, '0')}`
</script>

<template>
<table class="track-table" role="grid" aria-label="歌曲列表"><thead><tr class="track-table-head"><th scope="col">#</th><th scope="col">歌曲</th><th scope="col" class="track-album-heading">专辑</th><th scope="col">时长</th><th scope="col"><span class="sr-only">喜欢</span></th><th scope="col"><span class="sr-only">队列</span></th></tr></thead><tbody><tr v-for="(track, index) in tracks" :key="track.key" class="track-row" :class="{ current: currentKey === track.key, selected: selectedKey === track.key }" :aria-selected="selectedKey === track.key" tabindex="0" @click="emit('select', track.key)" @dblclick="emit('play', track)" @keydown.enter.prevent.stop="emit('play', track)" @keydown.space.prevent.stop="emit('select', track.key)"><td><button class="track-index" :aria-label="`${currentKey === track.key && playing ? '暂停' : '播放'} ${track.title}`" @click.stop="emit('toggle', track)" @dblclick.stop><span class="track-normal-icon"><AudioLines v-if="currentKey === track.key && playing" :size="16"/><span v-else>{{ String(index + 1).padStart(2, '0') }}</span></span><span class="track-hover-icon"><Pause v-if="currentKey === track.key && playing" :size="14" fill="currentColor"/><Play v-else :size="14" fill="currentColor"/></span></button></td><td><button class="track-name" @click.stop="emit('select', track.key)" @dblclick.stop="emit('play', track)" @keydown.enter.prevent.stop="emit('play', track)"><strong>{{ track.title }}</strong><small>{{ track.artist }}</small></button></td><td class="track-album-cell"><button class="track-album" @click.stop="emit('album', track.key)" @dblclick.stop>{{ track.album }}</button></td><td class="track-duration">{{ formatTime(track.duration) }}</td><td><button class="icon-button" :class="{ loved: favorites.has(track.key) }" :aria-label="`${favorites.has(track.key) ? '取消喜欢' : '喜欢'} ${track.title}`" @click.stop="emit('like', track.key)" @dblclick.stop><Heart :size="16" :fill="favorites.has(track.key) ? 'currentColor' : 'none'"/></button></td><td class="row-more-cell"><button class="row-more icon-button" :aria-label="`加入队列 ${track.title}`" @click.stop="emit('queue', track)" @dblclick.stop><Plus :size="17"/></button></td></tr></tbody></table>
</template>
